102: export function splitSegments(command) {
103:   const src = String(command ?? "");
104:   const out = [];
105:   let buf = "";
106:   let quote = null;
107:   const push = () => {
108:     if (buf.trim()) out.push(buf.trim());
109:     buf = "";
110:   };
111:   for (let i = 0; i < src.length; i++) {
112:     const c = src[i];
113:     if (quote) {
114:       buf += c;
115:       if (c === quote) quote = null;
116:       continue;
117:     }
118:     if (c === "'" || c === "\"") { quote = c; buf += c; continue; }
119:     if (c === ";") { push(); continue; }
120:     if (c === "&" && src[i + 1] === "&") { push(); i++; continue; }
121:     if (c === "|" && src[i + 1] === "|") { push(); i++; continue; }
122:     if (c === "|") { push(); continue; }
123:     buf += c;
124:   }
125:   push();
126:   return out;
127: }
