130: export function tokenize(segment) {
131:   const src = String(segment ?? "");
132:   const out = [];
133:   let buf = "";
134:   let quote = null;
135:   const push = () => {
136:     if (!buf) return;
137:     if (buf.length >= 2 && (buf[0] === "\"" || buf[0] === "'") && buf.at(-1) === buf[0]) buf = buf.slice(1, -1);
138:     if (buf) out.push(buf);
139:     buf = "";
140:   };
141:   for (const c of src) {
142:     if (quote) {
143:       buf += c;
144:       if (c === quote) { quote = null; push(); }
145:       continue;
146:     }
147:     if (c === "'" || c === "\"") { quote = c; buf += c; continue; }
148:     if (c === " " || c === "\t") { push(); continue; }
149:     buf += c;
150:   }
151:   push();
152:   return out;
